#include <iostream>
#include <exception>
#include <string>

struct MyError : std::exception {
    std::string msg;
    explicit MyError(const char* m) : msg(m) {}
    const char* what() const noexcept override { return msg.c_str(); }
};

int main() {
    try {
        throw MyError("custom failure");
    } catch (const std::exception& e) {   // 引用捕获：不切片，拿到派生 what()
        std::cout << e.what() << '\n';
    }
}
